mapper.select:
select id, app_code, name, mock_key, url, conditions, remark, created_at, created_by, updated_at, updated_by, deleted
from t_mock
where 1=1 and deleted=0

	and name like concat("%", #{name}, "%")


	and url like concat("%", #{url}, "%")


	and mock_key = #{mockKey}

and app_code = #{appCode}
limit #{offset}, #{pageSize}
